const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('저장할 수 없어요. 이번 화면에서만 기록을 유지해요.');return false}};
let page='home',scenarioId='adjust',farm=read('gul-v3-farm',{...RiskModel.defaults}),history=read('gul-v3-history',[]),inspection=read('gul-v3-inspection',null);
if(!RiskModel.validFarm(farm))farm={...RiskModel.defaults};if(!Array.isArray(history))history=[];
const scenarios={adjust:'조절 검토',keep:'현 배치 유지',danger:'모든 구간 위험',missing:'측정 누락',fault:'센서 이상',stale:'통신 지연'};
const interval=f=>`${f.top}~${f.bottom}m`,data=()=>RiskModel.scenario(scenarioId),analysis=()=>RiskModel.analyze(data(),farm);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function go(p){page=p;render();$('#screen').focus({preventScroll:true})}
function demoControl(){return `<label class="demo-select">시연 상황<select id="mobile-scenario" aria-label="시연 상황">${Object.entries(scenarios).map(([k,v])=>`<option value="${k}" ${k===scenarioId?'selected':''}>${v}</option>`).join('')}</select></label>`}
function quality(){return scenarioId==='stale'?'지연':scenarioId==='fault'||scenarioId==='missing'?'확인 필요':'가상 관측 정상'}
function basis(){return `<details><summary>기준·노출시간·신뢰도 설명</summary><p>가상 센서 1·2·3·4·5m, 10분 간격 6개 기록(09:30~10:30)을 사용합니다. 2·4m는 후보 비교 시연을 위해 추가한 가상 센서입니다.</p><p>시연 기준: 수온 28℃ 이상, 산소 3mg/L 미만, 염분 20~35 PSU 밖. 실제 굴의 안전기준이 아니며 현장 검증이 필요합니다.</p><p>구간 노출시간은 구간 안 측정점들의 최대 기준 초과시간입니다. 같은 과거 자료를 다른 배치에 적용한 비교이며 미래 예측이 아닙니다. 센서 사이 환경과 굴 분포 밀도는 확인되지 않았습니다.</p><p>측정 ${data().measured} / 수신 ${data().received} · 가상 현장 센서 · ${quality()}<br>기준 기반 분석 v3 · 학습 AI 미연결</p></details>`}
function home(){const d=data(),r=analysis(),m=d.rows[2],hot=d.rows.some(x=>x.temp>=28),low=d.rows.some(x=>x.oxygen<3),unknown=d.stale||d.rows.some(x=>x.quality!=='ok');return `${demoControl()}<div class="status ${unknown?'fault':''}"><span class="tag">${pictogram('alert')} 현재 상태: <b>${unknown?'확인 필요':hot&&low?'복합 주의':hot||low?'주의':'관측 양호'}</b></span><p>${unknown?'최신·정상 측정값부터 확인해 주세요.':hot&&low?'위쪽은 덥고, 아래쪽은 산소가 부족해요.':hot?'상층 고수온을 함께 살펴봐 주세요.':'수온과 산소 상태를 함께 확인했어요.'}</p></div><div class="hazards"><div><b>고수온 ${hot?'주의':'관측 양호'}</b><span>1m · ${d.rows[0].temp}℃</span><small>기준 초과 ${RiskModel.exposure(d.rows[0]).hot}분</small></div><div class="oxygen"><b>산소 ${unknown?'확인 필요':low?'부족':'관측 양호'}</b><span>5m · ${unknown?'사용 보류':d.rows[4].oxygen+' mg/L'}</span><small>${unknown?'노출시간 확인 불가':'기준 초과 '+RiskModel.exposure(d.rows[4]).low+'분'}</small></div></div><div class="section-label"><span>굴 구간 <b>${interval(farm)}</b></span><span>아래 숫자는 3m 관측</span></div>${[['temperature','수온',m.temp,'℃'],['oxygen','산소',m.oxygen,'mg/L'],['salinity','염분',m.salinity,'PSU']].map(([i,t,v,u])=>`<div class="metric"><span class="name">${icon(i)}${t}</span><strong>${d.stale?'—':v}<small>${u}</small></strong></div>`).join('')}<div class="measured">${pictogram('clock')} 측정 ${d.measured} · ${d.stale?'최신값 아님':'수신 '+d.received}</div><div class="home-cta"><button class="primary" data-go="recommend">${pictogram('robot')} 분석 결과 보기</button><p class="micro">${RiskModel.labels[r.type]} · 가상 데이터 · 기준 기반 분석</p></div>`}
function depths(){return `<p class="sub">현재 굴 <b>${interval(farm)}</b> · 수온과 산소를 함께 봐요.</p><div class="layers">${data().rows.map(x=>`<div class="layer ${x.depth>=farm.top&&x.depth<=farm.bottom?'occupied':''}"><b>${x.depth}m<small>${x.depth>=farm.top&&x.depth<=farm.bottom?'굴 위치':''}</small></b><div>${x.quality!=='ok'||data().stale?'<strong>측정 확인 필요</strong><small>분석에 사용하지 않음</small>':`<span>수온 <strong>${x.temp}℃</strong> <em class="${x.temp>=28?'warn':''}">${x.temp>=28?'주의':'양호'}</em></span><span>산소 <strong>${x.oxygen}</strong> <small>mg/L</small> <em class="${x.oxygen<3?'bad':''}">${x.oxygen<3?'부족':'양호'}</em></span>`}</div></div>`).join('')}</div><button class="primary" data-go="recommend">배치안 비교하기</button>${basis()}`}
function recommend(){const r=analysis();return `<section class="ai-review"><div class="review-heading"><span>수온·산소 복합 분석</span><span class="review-badge ${r.type}">${RiskModel.labels[r.type]}</span></div><h2>${r.type==='adjust'?'두 위험을 함께 살핀 후보예요':r.type==='keep'?'현재 배치가 더 유리해요':'지금은 추천을 보류해요'}</h2><p class="review-description">${r.reason}</p><div class="review-ranges"><div><span>현재 굴 구간</span><strong>${interval(farm)}</strong><small>구간 전체 비교</small></div><div class="${r.type==='hold'?'unavailable':''}"><span>${r.type==='adjust'?'검토할 후보':r.type==='keep'?'유지할 구간':'추천 구간'}</span><strong>${r.best?interval(r.best):'보류'}</strong><small>${r.best?r.best.method:'추가 확인 필요'}</small></div></div>${r.current?`<div class="exposure"><div><span>고수온 노출</span><b>${r.current.hot}분 → ${r.best?r.best.risk.hot+'분':'확인 필요'}</b></div><div><span>산소 부족 노출</span><b>${r.current.low}분 → ${r.best?r.best.risk.low+'분':'확인 필요'}</b></div></div><p class="micro">같은 과거 60분 자료로 배치별 비교 · 미래 예측 아님</p>`:'<div class="explain">측정 누락·센서 이상·통신 지연을 해소한 뒤 다시 판단해 주세요.</div>'}<p class="analysis-quality">자료 상태: ${quality()} · 측정 10:30<br>센서 사이 환경은 현장 확인 필요</p><div class="review-footer"><button class="primary" data-go="${r.type==='adjust'?'method':r.type==='keep'?'action':'device'}">${r.type==='adjust'?'작업 방법 확인':r.type==='keep'?'유지 판단 기록':'확인할 사항 보기'}</button><button class="text-button" data-go="compare">후보와 판단 근거 자세히</button></div></section>`}
function compare(){const r=analysis();return `<p class="sub">시설에서 가능한 작업만 비교해요. 시연은 1m 단위 후보입니다.</p>${r.candidates.length?r.candidates.map(c=>`<div class="candidate"><b>${c.method} · ${interval(c)}</b><p>${c.risk?`고수온 ${c.risk.hot}분 / 산소 부족 ${c.risk.low}분<br>염분 기준 초과 ${c.risk.salt}분`:'측정 범위 부족 · 후보 평가 제외'}</p></div>`).join(''):'<div class="explain">자료 품질을 먼저 확인해야 해요.</div>'}${basis()}<button class="primary" data-go="recommend">분석 결과로 돌아가기</button>`}
function method(){const r=analysis();if(r.type!=='adjust')return recommend();return `<div class="status good"><span class="tag">${r.best.method} 검토</span><h3>${interval(farm)} → ${interval(r.best)}</h3><p>${r.best.method==='하단 단축'?'위쪽 위치는 유지하고 아래쪽을 1m 줄이는 별도 작업입니다.':'수하연 전체 위치를 1m 이동하는 작업입니다.'}</p></div><ul class="reason"><li>시설에서 가능한 작업인지 확인해 주세요.</li><li>굴 구간 전체의 수온과 산소를 확인해 주세요.</li><li>앱 버튼은 장비를 움직이지 않아요.</li></ul><button class="primary" data-go="action">작업 후 기록하기</button><button class="secondary" id="defer">지금은 보류할게요</button><button class="text-button" data-go="settings">양식장 작업 범위 확인</button>`}
function action(){const r=analysis();if(r.type==='hold')return recommend();const target=r.best||farm;return `<p class="sub">현장 판단과 실제 작업 내용을 기록해 주세요.</p><form id="action-form"><label class="field" for="method">작업 방식</label><select id="method">${['유지','전체 인양','전체 침하','하단 단축'].map(m=>`<option ${m===target.method?'selected':''}>${m}</option>`).join('')}</select><div class="input-pair"><label>위쪽 수심 (m)<input id="top" type="number" min="1" step="0.1" required value="${target.top}"></label><label>아래쪽 수심 (m)<input id="bottom" type="number" min="1" step="0.1" required value="${target.bottom}"></label></div><label class="field" for="condition">눈으로 본 굴 상태</label><select id="condition"><option>확인 못함</option><option>변화 없음</option><option>이상 의심</option></select><label class="field" for="memo">메모 (선택)</label><textarea id="memo" maxlength="300" placeholder="현장에서 확인한 내용을 남겨 주세요"></textarea><p id="form-error" role="alert" class="form-error"></p><button class="primary" type="submit">✓ 기록 저장하기</button></form><p class="micro">기록은 이 브라우저에 저장됩니다. 관측자료는 시연 상황의 원래 배치를 유지합니다.</p>`}
function validateAction(method,top,bottom){if(!Number.isFinite(top)||!Number.isFinite(bottom)||top<1||bottom<=top||bottom+farm.clearance>farm.seabed)return '수심 순서와 해저 여유거리를 확인해 주세요.';const dt=+(farm.top-top).toFixed(3),db=+(farm.bottom-bottom).toFixed(3);if(method==='유지'&&(dt!==0||db!==0))return '유지는 현재 굴 구간과 같아야 해요.';if(method==='전체 인양'&&(!(dt>0)||dt!==db||dt>farm.lift))return '인양은 위·아래를 같은 거리만큼 올려야 해요. 허용 범위도 확인해 주세요.';if(method==='전체 침하'&&(!(dt<0)||dt!==db||-dt>farm.lower))return '침하는 위·아래를 같은 거리만큼 내려야 해요. 허용 범위도 확인해 주세요.';if(method==='하단 단축'&&(dt!==0||db<=0||db>farm.shorten))return '하단 단축은 위쪽 위치를 유지하고 허용 범위 안에서 아래쪽을 줄여야 해요.';return '';}
function records(){return `<p class="sub">작업·유지·보류 기록 · 이 브라우저에 저장</p>${history.length?history.slice(0,15).map(h=>`<div class="candidate"><b>${esc(h.method)} · ${esc(h.after||h.before)}</b><small>${esc(h.time)} · ${esc(scenarios[h.scenario]||'시연')}</small><p>${esc(h.before)} → ${esc(h.after||'조절 보류')}<br>굴 상태: ${esc(h.condition||'확인 못함')}<br>${esc(h.memo||'')}</p>${h.after?'<p class="pending">작업 후 새 측정값 대기 · 효과 확인 전</p>':''}</div>`).join(''):'<div class="explain">아직 기록이 없어요. 분석 결과에서 작업 또는 유지 판단을 남겨 주세요.</div>'}<button class="primary" data-go="recommend">분석 결과 보기</button><p class="micro">작업 후 환경 변화와 폐사·생육 개선은 별도로 확인해야 합니다.</p>`}
function device(){return `<p class="sub">${data().stale?'통신 지연 · 추천 보류':'마지막 통신 10:31 · 가상 장비'}</p>${[['buoy','부표 연결',data().stale?'끊김':'정상'],['battery','배터리','82%'],['sun','태양광','충전 중'],['alert','센서 상태',quality()],['calendar','점검 예정','12월 31일']].map(([i,k,v])=>`<div class="device"><span>${pictogram(i)}${k}</span><strong>${v}</strong></div>`).join('')}<div class="explain">${scenarioId==='fault'?'5m 센서에 이물질 부착 또는 장비 오류가 의심돼요. 점검 후 다시 측정해 주세요.':scenarioId==='missing'?'4m 자료가 없어 전체 굴 구간을 판단할 수 없어요. 해당 센서를 확인해 주세요.':data().stale?'최신 자료 수신이 필요해요. 부표 통신 상태를 확인해 주세요.':'점검 기록만으로 센서가 정상 복구되지는 않아요.'}</div><button class="primary" id="clean">점검·세척 기록 남기기</button>${inspection?`<p class="micro">마지막 점검: ${esc(inspection)}</p>`:''}<button class="text-button" data-go="settings">양식장 설정 · 시연 상황</button>`}
function settings(){return `${demoControl()}<p class="sub">시연용 시설 설정 · 분석에 즉시 반영돼요.</p><form id="settings-form">${[['top','굴 위쪽 수심'],['bottom','굴 아래쪽 수심'],['seabed','해저 수심'],['clearance','최저 해저 여유거리'],['lift','전체 인양 가능 거리'],['lower','전체 침하 가능 거리'],['shorten','하단 단축 가능 길이']].map(([k,t])=>`<label class="setting-row">${t} (m)<input name="${k}" type="number" required min="0" step="0.1" value="${farm[k]}"></label>`).join('')}<p class="micro">작업 불가 항목은 0. 현재 시연은 1m 단위 후보와 1~5m 가상 관측을 사용합니다.</p><p class="form-error" id="form-error" role="alert"></p><button type="submit" class="primary">설정 저장</button></form><button class="secondary" id="demo-reset">시연 설정 초기화</button>`}
function ocean(){return `<div class="ocean v3-ocean">${data().rows.map(r=>`<div class="depth-row ${r.depth>=farm.top&&r.depth<=farm.bottom?'in-range':''}" style="top:${(r.depth-1)*54}px"><b>${r.depth}m ${r.depth>=farm.top&&r.depth<=farm.bottom?'· 굴':''}</b><span>${r.quality!=='ok'||data().stale?'확인 필요':r.temp+'℃ / '+r.oxygen+' mg/L'}</span></div>`).join('')}</div>`}
function log(method,extra={}){const r=analysis();history.unshift({method,before:interval(farm),scenario:scenarioId,time:new Date().toLocaleString('ko-KR'),analysis:r.type,exposure:r.current,...extra});history=history.slice(0,100);save('gul-v3-history',history);go('records')}
function changeScenario(id){scenarioId=id;go('home')}
function render(){const titles={home:'가막만 굴 양식장 A',depths:'수심별 상태',recommend:'복합위험 분석',compare:'배치안 비교',method:'작업 방법 확인',action:'조치 기록',records:'조치 이력',device:'장비 상태',settings:'양식장 설정'};$('.location').textContent=titles[page];$('#screen').dataset.page=page;$('#screen').innerHTML=({home,depths,recommend,compare,method,action,records,device,settings}[page]||home)();$('#screen').scrollTop=0;$('#ocean').innerHTML=ocean();$('#nav').innerHTML=[['home','home','홈'],['depths','waves','수심분석'],['records','clipboard','조치기록'],['device','gear','장비관리']].map(([p,i,t])=>`<button data-go="${p}" class="${p===page||(p==='depths'&&['recommend','compare','method'].includes(page))?'active':''}"><span>${pictogram(i)}</span>${t}</button>`).join('');$('#steps').innerHTML=[['home','위험 확인'],['depths','수심 비교'],['recommend','분석 결과'],['records','판단 기록']].map(([p,t],i)=>`<button class="step ${page===p?'active':''}" data-go="${p}"><b>${i+1}</b>${t}</button>`).join('');$('#scenario').innerHTML=Object.entries(scenarios).map(([k,v])=>`<option value="${k}" ${k===scenarioId?'selected':''}>${v}</option>`).join('');document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));if($('#mobile-scenario'))$('#mobile-scenario').onchange=e=>changeScenario(e.target.value);if($('#defer'))$('#defer').onclick=()=>log('보류',{memo:'현장 작업 보류'});if($('#clean'))$('#clean').onclick=()=>{inspection=new Date().toLocaleString('ko-KR');save('gul-v3-inspection',inspection);render();toast('점검 기록 저장 · 재측정이 필요해요')};if($('#demo-reset'))$('#demo-reset').onclick=reset;if($('#action-form'))$('#action-form').onsubmit=e=>{e.preventDefault();const top=Number($('#top').value),bottom=Number($('#bottom').value),method=$('#method').value,error=validateAction(method,top,bottom);if(error){$('#form-error').textContent=error;return}log(method,{after:interval({top,bottom}),top,bottom,condition:$('#condition').value,memo:$('#memo').value.trim()})};if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();const next={};Object.keys(RiskModel.defaults).forEach(k=>next[k]=Number(e.target.elements[k].value));if(!RiskModel.validFarm(next)){$('#form-error').textContent='위·아래 수심, 해저 수심과 여유거리를 확인해 주세요.';return}farm=next;save('gul-v3-farm',farm);go('recommend')};}
function reset(){farm={...RiskModel.defaults};scenarioId='adjust';save('gul-v3-farm',farm);go('home');toast('시연 설정을 초기화했어요. 저장한 기록은 유지돼요.')}
$('#scenario').onchange=e=>changeScenario(e.target.value);$('#reset').onclick=reset;$('.brand').onclick=e=>{e.preventDefault();go('home')};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('브라우저 전체 화면을 사용해 주세요')}};render();
